1	type Item = { type: string; enchantment?: number };
2	
3	const BASE_PREMIUMS: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	};
10	
11	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
12	const COMPONENT_PRICE = 25;
13	const BLOCK_SIZE = 3;
14	const BLOCK_PRICE = 60;
15	
16	const priceOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
17	
18	const componentPremium = (count: number): number =>
19	  count === BLOCK_SIZE ? BLOCK_PRICE : count * COMPONENT_PRICE;
20	
21	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
22	
23	const countByType = (items: Item[]): Record<string, number> => {
24	  const counts: Record<string, number> = {};
25	  for (const item of items) {
26	    counts[item.type] = (counts[item.type] ?? 0) + 1;
27	  }
28	  return counts;
29	};
30	
31	export const basePremium = (items: Item[]): number => {
32	  const mainItems = items.filter((item) => !isComponent(item));
33	  const componentCounts = countByType(items.filter(isComponent));
34	
35	  const mainTotal = mainItems.reduce((sum, item) => sum + priceOf(item), 0);
36	  const componentTotal = Object.values(componentCounts).reduce(
37	    (sum, count) => sum + componentPremium(count),
38	    0,
39	  );
40	
41	  return mainTotal + componentTotal;
42	};
43	
44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_RATE = 0.1;
46	const LOYALTY_RATE = 0.2;
47	const LOYALTY_MIN_YEARS = 2;
48	const HIGH_ENCHANTMENT_RATE = 0.3;
49	const HIGH_ENCHANTMENT_MIN = 5;
50	
51	const itemSurcharge = (item: Item): number =>
52	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_MIN
53	    ? priceOf(item) * HIGH_ENCHANTMENT_RATE
54	    : 0;
55	
56	export const premium = (
57	  items: Item[],
58	  opts: { yearsWithMHPCO: number; isFollowUp: boolean },
59	): number => {
60	  const base = basePremium(items);
61	  const firstInsurance = base * FIRST_INSURANCE_RATE;
62	  const loyalty =
63	    opts.yearsWithMHPCO >= LOYALTY_MIN_YEARS ? base * LOYALTY_RATE : 0;
64	  const surcharges = items.reduce((sum, item) => sum + itemSurcharge(item), 0);
65	  return Math.ceil(base + firstInsurance - loyalty + surcharges + PROCESSING_FEE);
66	};
67	
