const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_MIN;

const itemSurcharge = (item: Item): number =>
  isHighlyEnchanted(item) ? priceOf(item) * HIGH_ENCHANTMENT_RATE : 0;
